import { NextResponse } from 'next/server'; import { session } from '../../../lib/session.mjs'; import { github } from '../../../lib/github.mjs';
const valid = repo => /^[\w.-]+\/[\w.-]+$/.test(repo);
export async function POST(request) { const s = await session(); if (!s) return NextResponse.json({ error:'Sign in required.' }, { status:401 }); if (request.headers.get('x-csrf-token') !== s.csrf) return NextResponse.json({ error:'Invalid request token.' }, { status:403 }); try { const { action, repos = [], target, confirmation } = await request.json(); if (!['pin','unpin','unpinAll','delete','transfer'].includes(action)) throw Error('Unknown action.'); if (action === 'delete' && confirmation !== 'DELETE') throw Error('Type DELETE to confirm permanent deletion.'); if (action === 'transfer' && !/^[\w.-]+$/.test(target || '')) throw Error('Enter the destination account or organization for transfer.'); let list = repos; if (action === 'unpinAll') { const pinned = await github('/user/pinned_repositories?per_page=100', s.token); list = pinned.map(r => r.full_name); } if (!list.length || list.length > 100) throw Error('Choose between 1 and 100 repositories.'); const results=[]; for (const repo of list) { if (!valid(repo)) { results.push({repo,ok:false,error:'Invalid repository.'}); continue; } try { if (action==='delete') await github(`/repos/${repo}`,s.token,{method:'DELETE'}); else if (action==='transfer') await github(`/repos/${repo}/transfer`,s.token,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({new_owner:target})}); else await github(`/user/pinned_repositories/${repo}`,s.token,{method:action==='pin'?'PUT':'DELETE'}); results.push({repo,ok:true}); } catch(e) { results.push({repo,ok:false,error:e.message}); } } return NextResponse.json({results}); } catch(e) { return NextResponse.json({error:e.message},{status:400}); } }
